<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div id="sc-enterprise-app"><div class="content"><div class="panel_s"><div class="panel-body"><div class="sc-enterprise-header"><div><h1><?php echo html_escape($title); ?></h1><p><?php echo _l('enterprise_field_permissions_description'); ?></p></div></div><form method="post" class="row"><?php echo form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()); ?><div class="col-md-2"><input class="form-control" name="resource_type" required placeholder="<?php echo _l('enterprise_source_type'); ?>"></div><div class="col-md-2"><input class="form-control" name="field_key" required placeholder="<?php echo _l('enterprise_field_key'); ?>"></div><div class="col-md-2"><select class="form-control" name="role_id"><option value="0"><?php echo _l('all_roles'); ?></option><?php foreach($roles as $role){?><option value="<?php echo (int)$role['roleid']; ?>"><?php echo html_escape($role['name']); ?></option><?php }?></select></div><div class="col-md-1"><label><input type="checkbox" name="can_view_own" value="1"> <?php echo _l('permission_view_own'); ?></label></div><div class="col-md-1"><label><input type="checkbox" name="can_view_global" value="1"> <?php echo _l('permission_view_global'); ?></label></div><div class="col-md-1"><label><input type="checkbox" name="can_edit" value="1"> <?php echo _l('permission_edit'); ?></label></div><div class="col-md-1"><label><input type="checkbox" name="can_export" value="1"> <?php echo _l('export'); ?></label></div><div class="col-md-2"><button class="btn btn-primary btn-block"><?php echo _l('save'); ?></button></div></form><hr><div class="sc-enterprise-data-wrap"><table class="table table-striped sc-enterprise-table"><thead><tr><th><?php echo _l('enterprise_source_type'); ?></th><th><?php echo _l('enterprise_field_key'); ?></th><th><?php echo _l('role'); ?></th><th><?php echo _l('permission_view_own'); ?></th><th><?php echo _l('permission_view_global'); ?></th><th><?php echo _l('permission_edit'); ?></th><th><?php echo _l('export'); ?></th><th><?php echo _l('options'); ?></th></tr></thead><tbody><?php foreach($rows as $r){?><tr><td><?php echo html_escape(ucwords(str_replace('_',' ',$r['resource_type']))); ?></td><td><?php echo html_escape(ucwords(str_replace('_',' ',$r['field_key']))); ?></td><td><?php echo (int)$r['role_id']; ?></td><td><?php echo !empty($r['can_view_own'])?_l('yes'):_l('no'); ?></td><td><?php echo !empty($r['can_view_global'])||!empty($r['can_view'])?_l('yes'):_l('no'); ?></td><td><?php echo !empty($r['can_edit'])?_l('yes'):_l('no'); ?></td><td><?php echo !empty($r['can_export'])?_l('yes'):_l('no'); ?></td><td><a class="btn btn-danger btn-xs _delete" href="<?php echo admin_url('smart_choice_enterprise_core/field_permission_delete/'.$r['id']); ?>"><i class="fa fa-trash"></i></a></td></tr><?php }?></tbody></table></div></div></div></div></div></div></div><?php init_tail(); ?>